  void onProtectionEvent(ScreenProtectionEventMessage event);

  static void setUp(
    ScreenProtectionFlutterApi? api, {
    BinaryMessenger? binaryMessenger,
    String messageChannelSuffix = '',
  }) {
    final String suffix = messageChannelSuffix.isNotEmpty
        ? '.$messageChannelSuffix'
        : '';
    {
      final BasicMessageChannel<Object?> pigeonVar_channel =
          BasicMessageChannel<Object?>(
            'dev.flutter.pigeon.xue_hua_screen_protection.ScreenProtectionFlutterApi.onProtectionEvent$suffix',
            pigeonChannelCodec,
            binaryMessenger: binaryMessenger,
          );
      if (api == null) {
        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          assert(
            message != null,
            'Argument for dev.flutter.pigeon.xue_hua_screen_protection.ScreenProtectionFlutterApi.onProtectionEvent was null.',
          );
          final List<Object?> args = (message as List<Object?>?)!;
          final ScreenProtectionEventMessage? arg_event =
              (args[0] as ScreenProtectionEventMessage?);
          assert(
            arg_event != null,
            'Argument for dev.flutter.pigeon.xue_hua_screen_protection.ScreenProtectionFlutterApi.onProtectionEvent was null, expected non-null ScreenProtectionEventMessage.',
          );
          try {
            api.onProtectionEvent(arg_event!);
            return wrapResponse(empty: true);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(
                code: 'error',
                message: e.toString(),
              ),
            );
          }
        });
      }
    }
  }
}
